def stream_rows(resource, transform):
    failed = False
    try:
        while True:
            try:
                row = resource.read_next()
                if row is None:
                    break
                value = transform(row)
            except BaseException:
                failed = True
                raise
            yield value
    finally:
        try:
            resource.close()
        except BaseException:
            if not failed:
                raise
